// v24.xx (belthover3), HIS ORDER (2026-10-12) and his #39 (full controller navigation): THE SAME CARD FOR THE KEY THE PAD FOCUSES.
// A controller has no pointer on the belt, so the card follows the pad focus (his layout of 2026-09-27): with the backpack open, the
// key the D-pad walk has on the belt row (G.bagBelt, G.bagBeltSel, ringed by drawBelt); with it shut, the key a bumper tap (LB or
// RB) lands on, for BELTPAD_T seconds after the tap. The same dwell, the same card and the same place as the mouse; it hides while
// RT is held (the trigger), during a pad drag, with the map or the pause box up, and while down. An item card names the pad buttons
// (RB to walk to it, RT to use it, through padB for a PlayStation pad). The Undercroft floor reads no D-pad and no bumper, so there
// it is the mouse only. Drawing only.
var BELTPAD_T=2.5;
function beltPadCell(now){
  var p=G&&G.player, C=G&&G.hotCells, ix=-1, k;
  if(!padOn()||!G||!C||!C.length||G.over||G.mapOpen||G.paused||pauseOpen||G.trade||G.drag||mouse.down||(p&&(p.downed||p.dying))) return null;
  if(G.bagOpen){ if(G.bagBelt) ix=clamp(G.bagBeltSel||0,0,C.length-1); }
  else if(state!=='hub'&&BELTHOV.padAt>0&&now-BELTHOV.padAt<BELTPAD_T) ix=hotSel();
  if(ix<0) return null;
  for(k=0;k<C.length;k++) if(C[k]&&C[k].i===ix) return C[k];
  return null;
}
function beltHoverHud(){
  var now=beltHovNow(), c, S, g, cmp, rs, m, sz, xR, yB, p=G&&G.player, src;
  BELTHOV.box=null;
  c=beltPadCell(now); src=c?'pad':'mouse';   // v24.xx (belthover3): the pad focus first
  if(!c) c=beltHovOff()?null:beltHovCell();
  if(!c){ BELTHOV.i=-1; return null; }
  if(c.i!==BELTHOV.i||BELTHOV.st!==state||BELTHOV.src!==src){ BELTHOV.i=c.i; BELTHOV.at=now; BELTHOV.st=state; BELTHOV.src=src; return null; }

